module TopModule (
  input  [3:0] in,
  output [3:0] out_both,
  output [3:0] out_any,
  output [3:0] out_different
);

  // out_both[i] = in[i] & in[i+1]; bit 3 is unused and driven to 0
  assign out_both = {1'b0, in[3:1] & in[2:0]};

  // out_any[i] = in[i] | in[i-1]; bit 0 is unused and equals in[0]
  assign out_any = in | {in[2:0], 1'b0};

  // out_different[i] = in[i] ^ in[(i+1)%4], with wrap-around
  assign out_different = in ^ {in[0], in[3:1]};

endmodule

