module TopModule (
    input  clk,
    input  reset,
    input  in,
    output done
);

    localparam IDLE = 3'd0;
    localparam DATA = 3'd1;
    localparam STOP = 3'd2;
    localparam ERR  = 3'd3;
    localparam DONE = 3'd4;

    reg [2:0] state, next;
    reg [3:0] cnt;

    // State register (synchronous, active-high reset)
    always @(posedge clk) begin
        if (reset)
            state <= IDLE;
        else
            state <= next;
    end

    // Bit counter for the 8 data bits
    always @(posedge clk) begin
        if (reset)
            cnt <= 4'd0;
        else if (state == DATA)
            cnt <= cnt + 4'd1;
        else
            cnt <= 4'd0;
    end

    // Next-state logic
    always @(*) begin
        next = state;
        case (state)
            IDLE: if (!in) next = DATA;
            DATA: if (cnt == 4'd7) next = STOP;
            STOP: next = in ? DONE : ERR;
            ERR:  if (in) next = IDLE;
            DONE: next = in ? IDLE : DATA;
            default: next = IDLE;
        endcase
    end

    assign done = (state == DONE);

endmodule

