module TopModule (
    input  clk,
    input  reset,
    input  s,
    input  w,
    output reg z
);

    reg       in_b;
    reg [1:0] cnt;
    reg [1:0] ones;

    always @(posedge clk) begin
        if (reset) begin
            in_b <= 1'b0;
            cnt  <= 2'd0;
            ones <= 2'd0;
            z    <= 1'b0;
        end else if (!in_b) begin
            z    <= 1'b0;
            cnt  <= 2'd0;
            ones <= 2'd0;
            if (s)
                in_b <= 1'b1;
        end else begin
            if (cnt == 2'd2) begin
                z    <= ((ones + {1'b0, w}) == 2'd2);
                cnt  <= 2'd0;
                ones <= 2'd0;
            end else begin
                z    <= 1'b0;
                cnt  <= cnt + 2'd1;
                ones <= ones + {1'b0, w};
            end
        end
    end

endmodule

