module TopModule (
    input  clk,
    input  reset,
    input  s,
    input  w,
    output z
);

    localparam A  = 4'd0,
               B  = 4'd1,
               C0 = 4'd2,
               C1 = 4'd3,
               D0 = 4'd4,
               D1 = 4'd5,
               D2 = 4'd6,
               E  = 4'd7;

    reg [3:0] state, next;

    always @(*) begin
        case (state)
            A:  next = s ? B : A;
            B:  next = w ? C1 : C0;
            E:  next = w ? C1 : C0;
            C0: next = w ? D1 : D0;
            C1: next = w ? D2 : D1;
            D0: next = B;
            D1: next = w ? E : B;
            D2: next = w ? B : E;
            default: next = A;
        endcase
    end

    always @(posedge clk) begin
        if (reset)
            state <= A;
        else
            state <= next;
    end

    assign z = (state == E);

endmodule

