module TopModule (
    input  clk,
    input  reset,
    input  s,
    input  w,
    output reg z
);

    reg       started;  // 0: state A, 1: state B (checking w)
    reg [1:0] phase;    // position within the 3-cycle window (0..2)
    reg [1:0] cnt;      // number of w=1 seen so far in the current window

    always @(posedge clk) begin
        if (reset) begin
            started <= 1'b0;
            phase   <= 2'd0;
            cnt     <= 2'd0;
            z       <= 1'b0;
        end else begin
            if (!started) begin
                // State A: wait for s = 1
                z       <= 1'b0;
                phase   <= 2'd0;
                cnt     <= 2'd0;
                if (s)
                    started <= 1'b1;
            end else begin
                // State B: examine w over consecutive 3-cycle windows
                if (phase == 2'd2) begin
                    // Third sample of the window: z = 1 next cycle iff exactly two w=1
                    z     <= ((cnt + w) == 2'd2);
                    phase <= 2'd0;
                    cnt   <= 2'd0;
                end else begin
                    z     <= 1'b0;
                    phase <= phase + 2'd1;
                    cnt   <= cnt + {1'b0, w};
                end
            end
        end
    end

endmodule

