module TopModule (
    input  clk,
    input  reset,
    input  [2:0] s,
    output fr2,
    output fr1,
    output fr0,
    output dfr
);

    // Registered previous sensor count and direction of last sensor change
    reg [1:0] prev_cnt;
    reg       rise_q;      // 1 = level rose at last sensor change, 0 = fell

    // Number of asserted sensors (3 = above s[2], 0 = below s[0])
    wire [1:0] cnt = {1'b0, s[0]} + {1'b0, s[1]} + {1'b0, s[2]};

    // Direction of most recent sensor change (hold previous if no change)
    wire rise_eff = (cnt > prev_cnt) ? 1'b1 :
                    (cnt < prev_cnt) ? 1'b0 : rise_q;

    always @(posedge clk) begin
        if (reset) begin
            prev_cnt <= 2'd0;   // as if water had been low for a long time
            rise_q   <= 1'b1;   // all four outputs asserted
        end else begin
            prev_cnt <= cnt;
            rise_q   <= rise_eff;
        end
    end

    // Nominal flow valves
    assign fr2 = (cnt == 2'd0);
    assign fr1 = (cnt <  2'd2);
    assign fr0 = (cnt != 2'd3);

    // Supplemental flow valve:
    //   zero flow above s[2]        -> closed
    //   below s[0] (max flow)       -> open
    //   otherwise                   -> open only if level rose at last change
    assign dfr = (cnt != 2'd3) & (rise_eff | (cnt == 2'd0));

endmodule

