module TopModule (
    input  clk,
    input  reset,
    input  [2:0] s,
    output fr2,
    output fr1,
    output fr0,
    output dfr
);

    localparam A2 = 3'd0,  // below s[0]
               B1 = 3'd1,  // between s[0] and s[1], reached from below
               B2 = 3'd2,  // between s[0] and s[1], reached from above
               C1 = 3'd3,  // between s[1] and s[2], reached from below
               C2 = 3'd4,  // between s[1] and s[2], reached from above
               D1 = 3'd5;  // above s[2]

    reg [2:0] state, next;

    always @(posedge clk) begin
        if (reset)
            state <= A2;
        else
            state <= next;
    end

    always @(*) begin
        case (state)
            A2: next = s[0] ? B1 : A2;
            B1: next = s[1] ? C1 : (s[0] ? B1 : A2);
            B2: next = s[1] ? C1 : (s[0] ? B2 : A2);
            C1: next = s[2] ? D1 : (s[1] ? C1 : B2);
            C2: next = s[2] ? D1 : (s[1] ? C2 : B2);
            D1: next = s[2] ? D1 : C2;
            default: next = A2;
        endcase
    end

    reg [3:0] fr;
    assign {fr2, fr1, fr0, dfr} = fr;

    always @(*) begin
        case (state)
            A2: fr = 4'b1111;
            B1: fr = 4'b0110;
            B2: fr = 4'b0111;
            C1: fr = 4'b0010;
            C2: fr = 4'b0011;
            D1: fr = 4'b0000;
            default: fr = 4'b1111;
        endcase
    end

endmodule

