    input  clock,
    input  a,
    output reg p,
    output reg q
);

    // p: transparent while clock is high, holds while clock is low
    always @(clock or a) begin
        if (clock)
            p <= a;
    end

    // q: transparent while clock is low, holds while clock is high
    always @(clock or p) begin
        if (!clock)
            q <= p;
    end

endmodule

