module TopModule (
  input  wire        clk,
  input  wire        reset,
  input  wire [7:0]  in,
  output reg  [23:0] out_bytes,
  output reg         done
);

  localparam SEARCH = 2'd0;
  localparam B2     = 2'd1;
  localparam B3     = 2'd2;

  reg [1:0] state;
  reg [7:0] byte1;
  reg [7:0] byte2;

  always @(posedge clk) begin
    if (reset) begin
      state     <= SEARCH;
      byte1     <= 8'd0;
      byte2     <= 8'd0;
      out_bytes <= 24'd0;
      done      <= 1'b0;
    end else begin
      done <= 1'b0;
      case (state)
        SEARCH: begin
          if (in[3]) begin
            byte1 <= in;
            state <= B2;
          end
        end
        B2: begin
          byte2 <= in;
          state <= B3;
        end
        B3: begin
          out_bytes <= {byte1, byte2, in};
          done      <= 1'b1;
          state     <= SEARCH;
        end
        default: state <= SEARCH;
      endcase
    end
  end

endmodule

