module TopModule (
    input  wire       clk,
    input  wire       reset,
    input  wire       data,
    output wire [3:0] count,
    output wire       counting,
    output wire       done,
    input  wire       ack
);

    localparam [1:0] S_SEARCH = 2'd0,
                     S_DELAY  = 2'd1,
                     S_COUNT  = 2'd2,
                     S_DONE   = 2'd3;

    reg [1:0] state;
    reg [3:0] sr;
    reg [1:0] bit_cnt;
    reg [3:0] delay_reg;
    reg [3:0] rem;
    reg [9:0] cyc;

    always @(posedge clk) begin
        if (reset) begin
            state     <= S_SEARCH;
            sr        <= 4'd0;
            bit_cnt   <= 2'd0;
            delay_reg <= 4'd0;
            rem       <= 4'd0;
            cyc       <= 10'd0;
        end else begin
            case (state)
                S_SEARCH: begin
                    sr <= {sr[2:0], data};
                    if ({sr[2:0], data} == 4'b1101) begin
                        state   <= S_DELAY;
                        bit_cnt <= 2'd0;
                    end
                end

                S_DELAY: begin
                    delay_reg <= {delay_reg[2:0], data};
                    bit_cnt   <= bit_cnt + 2'd1;
                    if (bit_cnt == 2'd3) begin
                        state <= S_COUNT;
                        rem   <= {delay_reg[2:0], data};
                        cyc   <= 10'd0;
                    end
                end

                S_COUNT: begin
                    if (cyc == 10'd999) begin
                        cyc <= 10'd0;
                        if (rem == 4'd0) begin
                            state <= S_DONE;
                        end else begin
                            rem <= rem - 4'd1;
                        end
                    end else begin
                        cyc <= cyc + 10'd1;
                    end
                end

                S_DONE: begin
                    if (ack) begin
                        state <= S_SEARCH;
                        sr    <= 4'd0;
                    end
                end

                default: state <= S_SEARCH;
            endcase
        end
    end

    assign count    = rem;
    assign counting = (state == S_COUNT);
    assign done     = (state == S_DONE);

endmodule

