                     WR    = 3'd1,  // walking right
                     FALLL = 3'd2,  // falling, will resume walking left
                     FALLR = 3'd3,  // falling, will resume walking right
                     DIGL  = 3'd4,  // digging, facing left
                     DIGR  = 3'd5,  // digging, facing right
                     SPLAT = 3'd6;  // splattered, all outputs 0

    reg [2:0] state, next_state;
    reg [4:0] fall_cnt;  // saturating count of cycles spent falling

    wire falling = (state == FALLL) || (state == FALLR);

    // State register with asynchronous reset to walking left
    always @(posedge clk or posedge areset) begin
        if (areset)
            state <= WL;
        else
            state <= next_state;
    end

    // Fall counter
    always @(posedge clk or posedge areset) begin
        if (areset)
            fall_cnt <= 5'd0;
        else if (falling) begin
            if (fall_cnt != 5'd31)
                fall_cnt <= fall_cnt + 5'd1;
        end
        else
            fall_cnt <= 5'd0;
    end

    // Next-state logic
    always @(*) begin
        next_state = state;
        case (state)
            WL: begin
                if (!ground)
                    next_state = FALLL;          // fall has highest precedence
                else if (dig)
                    next_state = DIGL;           // dig next
                else if (bump_left)
                    next_state = WR;             // bumped on left: walk right
                else
                    next_state = WL;
            end

            WR: begin
                if (!ground)
                    next_state = FALLR;
                else if (dig)
                    next_state = DIGR;
                else if (bump_right)
                    next_state = WL;             // bumped on right: walk left
                else
                    next_state = WR;
            end

            FALLL: begin
                if (ground) begin
                    if (fall_cnt > 5'd20)
                        next_state = SPLAT;      // long fall: splatter
                    else
                        next_state = WL;         // resume walking left
                end
                else
                    next_state = FALLL;          // bumps ignored while falling
            end

            FALLR: begin
                if (ground) begin
                    if (fall_cnt > 5'd20)
                        next_state = SPLAT;
                    else
                        next_state = WR;
                end
                else
                    next_state = FALLR;
            end

            DIGL: begin
                if (!ground)
                    next_state = FALLL;          // dug through: fall
                else
                    next_state = DIGL;           // keep digging, bumps ignored
            end

            DIGR: begin
                if (!ground)
                    next_state = FALLR;
                else
                    next_state = DIGR;
            end

            SPLAT: next_state = SPLAT;           // stays dead until reset

            default: next_state = WL;
        endcase
    end

